'use client';
import {useMemo,useState} from 'react';
export default function ObraDetalheClient(){const [sale,setSale]=useState(15800),[materials,setMaterials]=useState(4200),[labour,setLabour]=useState(3100),[other,setOther]=useState(650);const cost=materials+labour+other,profit=sale-cost,margin=sale?profit/sale*100:0;const fields=[['Venda',sale,setSale],['Materiais',materials,setMaterials],['Mão de obra',labour,setLabour],['Outros custos',other,setOther]] as const;return <main style={{padding:32,fontFamily:'Arial',maxWidth:1100}}><h1>Obra RE-2026-024</h1><p>Ficha completa da obra: medições, equipa, materiais, extras, custos e rentabilidade.</p><section style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:15}}>{[['Venda',sale],['Materiais',materials],['Mão de obra',labour],['Outros custos',other],['Custo total',cost],['Lucro',profit]].map(([l,v])=><div key={l as string} style={{padding:18,border:'1px solid #ddd',borderRadius:12}}><small>{l}</small><h2>€{(v as number).toFixed(2)}</h2></div>)}</section><div style={{marginTop:18,padding:18,border:'1px solid #ddd',borderRadius:12}}><strong>Margem real: {margin.toFixed(1)}%</strong></div><h2>Custos reais</h2><div style={{display:'grid',gap:10,maxWidth:500}}>{fields.map(([label,value,set])=><label key={label}>{label}<input type="number" value={value} onChange={e=>set(+e.target.value)} style={{display:'block',width:'100%',padding:9}}/></label>)}</div><h2>Operações</h2><p>Registar horas, consumo de material, despesas, pagamentos, trabalhos extra e fotografias da obra.</p></main>}
